//! JWT authentication for projects generated by the `trust` compiler.
//!
//! A handler of a route declared with `auth {}` / `auth: required` takes a
//! [`UserContext`] argument: the request is rejected with 401 unless it
//! carries `Authorization: Bearer <token>`, an HS256 JWT signed with the
//! `JWT_SECRET` environment variable whose claims hold a `user_id`.

use axum::{
    Json,
    extract::FromRequestParts,
    http::{HeaderMap, StatusCode, request::Parts},
};
use jsonwebtoken::{Algorithm, DecodingKey, Validation, decode};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

/// Claims expected in the bearer token.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct JwtClaims {
    pub sub: String,
    pub user_id: i64,
    pub exp: usize,
}

/// The authenticated caller.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UserContext {
    pub user_id: i64,
}

type Rejection = (StatusCode, Json<Value>);

fn reject(status: StatusCode, message: impl Into<String>) -> Rejection {
    (status, Json(json!({ "error": message.into() })))
}

/// Validates the bearer token of `headers` against `secret`.
pub fn validate_token(headers: &HeaderMap, secret: &str) -> Result<UserContext, Rejection> {
    let header = headers
        .get("authorization")
        .and_then(|h| h.to_str().ok())
        .ok_or_else(|| reject(StatusCode::UNAUTHORIZED, "Missing authorization header"))?;
    let token = header
        .strip_prefix("Bearer ")
        .ok_or_else(|| reject(StatusCode::UNAUTHORIZED, "Invalid authorization format"))?;
    let data = decode::<JwtClaims>(
        token,
        &DecodingKey::from_secret(secret.as_bytes()),
        &Validation::new(Algorithm::HS256),
    )
    .map_err(|e| reject(StatusCode::UNAUTHORIZED, format!("Invalid token: {}", e)))?;
    Ok(UserContext { user_id: data.claims.user_id })
}

fn from_env(headers: &HeaderMap) -> Result<UserContext, Rejection> {
    let secret = std::env::var("JWT_SECRET")
        .map_err(|_| reject(StatusCode::INTERNAL_SERVER_ERROR, "JWT_SECRET not configured"))?;
    validate_token(headers, &secret)
}

impl<S: Send + Sync> FromRequestParts<S> for UserContext {
    type Rejection = Rejection;

    async fn from_request_parts(parts: &mut Parts, _state: &S) -> Result<Self, Self::Rejection> {
        from_env(&parts.headers)
    }
}

/// Like [`UserContext`], but a missing or invalid token yields `None`
/// instead of a 401.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OptionalUserContext(pub Option<UserContext>);

impl<S: Send + Sync> FromRequestParts<S> for OptionalUserContext {
    type Rejection = std::convert::Infallible;

    async fn from_request_parts(parts: &mut Parts, _state: &S) -> Result<Self, Self::Rejection> {
        Ok(Self(from_env(&parts.headers).ok()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use jsonwebtoken::{EncodingKey, Header, encode};

    fn bearer(token: &str) -> HeaderMap {
        let mut headers = HeaderMap::new();
        headers.insert("authorization", format!("Bearer {}", token).parse().unwrap());
        headers
    }

    #[test]
    fn accepts_a_valid_token_and_rejects_others() {
        let claims = JwtClaims { sub: "7".into(), user_id: 7, exp: usize::MAX / 2 };
        let token = encode(&Header::default(), &claims, &EncodingKey::from_secret(b"s3cret")).unwrap();
        assert_eq!(validate_token(&bearer(&token), "s3cret").unwrap().user_id, 7);
        assert_eq!(validate_token(&bearer(&token), "other").unwrap_err().0, StatusCode::UNAUTHORIZED);
        assert_eq!(validate_token(&HeaderMap::new(), "s3cret").unwrap_err().0, StatusCode::UNAUTHORIZED);
    }
}
